export function ahavatBeforePublicReading(page) {
  const edits = AHAVAT_PUBLIC_READING_EDITS.filter(edit => edit.page === page.pdf_page);
  if (!edits.length) return page;
  return { ...page, companion_units: page.companion_units?.map(unit => {
    const edit = edits.find(edit => edit.id === unit.id);
    return edit && unit[edit.field] === edit.after ? { ...unit, [edit.field]: edit.before } : unit;
  }) };
}

